from pathlib import Path

workspace = Path('app/pages/workspace.vue')
text = workspace.read_text()

def r(old: str, new: str, label: str):
    global text
    if old not in text:
        raise SystemExit(f'Missing target: {label}')
    text = text.replace(old, new, 1)

r("const bookingSearch = ref('')\nconst sidebarCollapsed = ref(false)", "const bookingSearch = ref('')\nconst historySearch = ref('')\nconst historyPage = ref(1)\nconst historyPageSize = 10\nconst sidebarCollapsed = ref(false)", 'history refs')
r("searchBookings: 'Buscar solicitudes', searchBookingsPlaceholder: 'Sala, promotor, ciudad, evento o ID…', searchResults: 'resultados',", "searchBookings: 'Buscar solicitudes', searchBookingsPlaceholder: 'Sala, promotor, ciudad, evento o ID…', searchResults: 'resultados', searchHistory: 'Buscar en historial', searchHistoryPlaceholder: 'Sala, ciudad, mensaje o estado…', previousPage: 'Anterior', nextPage: 'Siguiente', page: 'Página',", 'Spanish history copy')
r("searchBookings: 'Search requests', searchBookingsPlaceholder: 'Venue, promoter, city, event or ID…', searchResults: 'results',", "searchBookings: 'Search requests', searchBookingsPlaceholder: 'Venue, promoter, city, event or ID…', searchResults: 'results', searchHistory: 'Search history', searchHistoryPlaceholder: 'Venue, city, message or status…', previousPage: 'Previous', nextPage: 'Next', page: 'Page',", 'English history copy')

old_hist = "const historyItems = computed(() => demo.bookings.value.flatMap(booking => [\n  ...booking.messages.map(message => ({\n    id: message.id,\n    bookingId: booking.id,\n    at: message.createdAt,\n    kind: copy.value.historyMessage,\n    title: `${message.actor === 'artist' ? booking.artistName : booking.promoter.name} · ${booking.event.venue}`,\n    detail: message.body\n  })),\n  {\n    id: `status-${booking.id}`,\n    bookingId: booking.id,\n    at: booking.updatedAt,\n    kind: copy.value.historyStatus,\n    title: `${booking.event.venue} · ${demoStatusLabel(booking.status)}`,\n    detail: `${booking.event.city} · ${formatDemoDate(booking.event.date)}`\n  }\n]).sort((a, b) => b.at.localeCompare(a.at)))"
new_hist = old_hist + "\nconst filteredHistoryItems = computed(() => {\n  const query = historySearch.value.trim().toLocaleLowerCase(preferences.locale.value === 'es' ? 'es' : 'en')\n  if (!query) return historyItems.value\n  return historyItems.value.filter(item => [item.kind, item.title, item.detail].join(' ').toLocaleLowerCase(preferences.locale.value === 'es' ? 'es' : 'en').includes(query))\n})\nconst historyPageCount = computed(() => Math.max(1, Math.ceil(filteredHistoryItems.value.length / historyPageSize)))\nconst paginatedHistoryItems = computed(() => {\n  const start = (historyPage.value - 1) * historyPageSize\n  return filteredHistoryItems.value.slice(start, start + historyPageSize)\n})"
r(old_hist, new_hist, 'history computed')
r("watch(rosterArtistName, value => { rosterArtistSlug.value = slugify(value) })", "watch(rosterArtistName, value => { rosterArtistSlug.value = slugify(value) })\nwatch(historySearch, () => { historyPage.value = 1 })\nwatch(historyPageCount, count => { if (historyPage.value > count) historyPage.value = count })\nwatch(activeView, view => { if (view !== 'profile') profilePreviewOpen.value = false })", 'history watchers')

r("function selectDay(date: string) {\n  selectedDate.value = date\n  if (date.slice(0, 7) !== monthCursor.value.slice(0, 7)) monthCursor.value = `${date.slice(0, 7)}-01`\n  closeEditor()\n}", "async function selectDay(date: string) {\n  selectedDate.value = date\n  if (date.slice(0, 7) !== monthCursor.value.slice(0, 7)) monthCursor.value = `${date.slice(0, 7)}-01`\n  closeEditor()\n  if (!import.meta.client || window.innerWidth > 960) return\n  await nextTick()\n  await new Promise<void>(resolve => requestAnimationFrame(() => resolve()))\n  const panel = document.getElementById('workspace-day-panel')\n  const header = document.getElementById('workspace-header')\n  if (!panel) return\n  const offset = (header?.getBoundingClientRect().height || 0) + 8\n  const top = panel.getBoundingClientRect().top + window.scrollY - offset\n  window.scrollTo({ top: Math.max(0, top), behavior: prefersReducedMotion() ? 'auto' : 'smooth' })\n}", 'calendar autoscroll')
r("  const headerOffset = header ? Math.ceil(header.getBoundingClientRect().height) + 8 : 16\n  const top = detail.getBoundingClientRect().top + window.scrollY - headerOffset", "  const headerOffset = header ? Math.ceil(header.getBoundingClientRect().height) + 12 : 16\n  const detailHeader = detail.querySelector<HTMLElement>(':scope > header') || detail\n  const top = detailHeader.getBoundingClientRect().top + window.scrollY - headerOffset", 'booking title scroll')
r('<section class="day-panel panel">', '<section id="workspace-day-panel" class="day-panel panel">', 'day panel id')
r("<button class=\"profile-preview-button\" type=\"button\" @click=\"profilePreviewOpen = true\">{{ copy.previewProfile }} ↗</button>", "<button class=\"profile-preview-button\" type=\"button\" @click=\"profilePreviewOpen = true\"><span>{{ copy.previewProfile }}</span><svg class=\"external-link-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 17 17 7M9 7h8v8\"/></svg></button>", 'preview svg')
r("<div v-if=\"profilePreviewLinks.length\" class=\"profile-preview-block\"><span>{{ copy.previewLinks }}</span><nav><a v-for=\"link in profilePreviewLinks\" :key=\"link.label\" :href=\"link.url\" target=\"_blank\" rel=\"noopener noreferrer\">{{ link.label }} ↗</a></nav></div>", "<div v-if=\"profilePreviewLinks.length\" class=\"profile-preview-block\"><span>{{ copy.previewLinks }}</span><nav><a v-for=\"link in profilePreviewLinks\" :key=\"link.label\" :href=\"link.url\" target=\"_blank\" rel=\"noopener noreferrer\"><span>{{ link.label }}</span><svg class=\"external-link-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 17 17 7M9 7h8v8\"/></svg></a></nav></div>", 'preview links svg')

old_history_markup = '''        <div v-if="historyItems.length" class="history-list">\n          <button v-for="item in historyItems" :id="item.id === `status-${item.bookingId}` ? `history-booking-${item.bookingId}` : undefined" :key="item.id" type="button" :aria-label="`${copy.openTrace}: ${item.title}`" @click="openHistoryItem(item.bookingId)"><time>{{ formatDemoTime(item.at) }}</time><i /><div><span>{{ item.kind }}</span><strong>{{ item.title }}</strong><p>{{ item.detail }}</p><small>{{ copy.openTrace }} →</small></div></button>\n        </div>\n        <p v-else class="workspace-empty">{{ copy.historyEmpty }}</p>'''
new_history_markup = '''        <div v-if="historyItems.length" class="history-tools">\n          <label class="booking-search history-search">\n            <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/></svg>\n            <span class="sr-only">{{ copy.searchHistory }}</span>\n            <input v-model="historySearch" type="search" :placeholder="copy.searchHistoryPlaceholder" :aria-label="copy.searchHistory">\n          </label>\n          <span>{{ filteredHistoryItems.length }} / {{ historyItems.length }}</span>\n        </div>\n        <div v-if="paginatedHistoryItems.length" class="history-list">\n          <button v-for="item in paginatedHistoryItems" :id="item.id === `status-${item.bookingId}` ? `history-booking-${item.bookingId}` : undefined" :key="item.id" type="button" :aria-label="`${copy.openTrace}: ${item.title}`" @click="openHistoryItem(item.bookingId)"><time>{{ formatDemoTime(item.at) }}</time><i /><div><span>{{ item.kind }}</span><strong>{{ item.title }}</strong><p>{{ item.detail }}</p><small>{{ copy.openTrace }} <svg class="inline-arrow-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h13M13 7l5 5-5 5"/></svg></small></div></button>\n        </div>\n        <div v-if="filteredHistoryItems.length > historyPageSize" class="history-pagination" aria-label="Pagination">\n          <button type="button" :disabled="historyPage <= 1" @click="historyPage -= 1">{{ copy.previousPage }}</button>\n          <span>{{ copy.page }} {{ historyPage }} / {{ historyPageCount }}</span>\n          <button type="button" :disabled="historyPage >= historyPageCount" @click="historyPage += 1">{{ copy.nextPage }}</button>\n        </div>\n        <p v-if="!paginatedHistoryItems.length" class="workspace-empty">{{ copy.historyEmpty }}</p>'''
r(old_history_markup, new_history_markup, 'history search markup')
workspace.write_text(text)

css = Path('assets/css/workspace-responsive-final.css')
c = css.read_text()
base = '''\n/* Mobile UX pass: predictable scrolling, compact sticky actions, scalable history and profile preview. */\n.external-link-icon,.inline-arrow-icon{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:0 0 auto}\n.profile-preview-button,.profile-preview-block a,.history-list small{display:inline-flex;align-items:center;gap:7px}\n.history-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:14px 0 10px}\n.history-tools>span{color:var(--cue-muted);font:700 9px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.08em}\n.history-pagination{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 0 6px;border-top:1px solid var(--workspace-line,var(--cue-border))}\n.history-pagination button{min-height:38px;padding:0 14px;border:1px solid var(--workspace-line,var(--cue-border));background:var(--workspace-panel,var(--cue-surface));color:var(--cue-text)}\n.history-pagination button:disabled{opacity:.35}\n.history-pagination span{color:var(--cue-muted);font:700 9px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.08em}\n'''
if 'Mobile UX pass: predictable scrolling' not in c:
    c = base + c
marker='@media (max-width: 960px) {'
mobile='''\n  .workspace .profile-cover-field .cover-uploader__intro button{margin-top:12px!important}\n  .workspace .profile-savebar{position:sticky!important;z-index:56!important;bottom:env(safe-area-inset-bottom)!important;grid-template-columns:minmax(0,1fr) auto!important;align-items:center!important;gap:10px!important;margin:0!important;padding:10px 12px!important;border-top:1px solid var(--workspace-line,var(--cue-border))!important;background:color-mix(in srgb,var(--cue-bg) 96%,transparent)!important;box-shadow:0 -10px 28px rgba(0,0,0,.32)!important;backdrop-filter:blur(16px)!important}\n  .workspace .profile-savebar>div{display:flex!important;align-items:baseline!important;gap:9px!important;min-width:0!important}\n  .workspace .profile-savebar>div span{font-size:8px!important}.workspace .profile-savebar>div strong{font-size:22px!important}\n  .workspace .profile-savebar>button{width:auto!important;min-width:116px!important;min-height:44px!important;padding-inline:16px!important}\n  .workspace .profile-savebar>p{grid-column:1/-1!important;grid-row:2!important;margin:0!important}\n  .workspace .history-tools{display:grid!important;grid-template-columns:1fr auto!important;margin-top:12px!important}.workspace .history-search{max-width:none!important}.workspace .history-search input{min-height:44px!important}.workspace .history-pagination button{min-height:44px!important}\n  .workspace .booking-detail,.workspace #workspace-day-panel{scroll-margin-top:calc(var(--workspace-mobile-safe-header,108px) + 12px)!important}\n  .workspace .profile-preview-backdrop{position:fixed!important;z-index:80!important;inset:var(--workspace-mobile-safe-header,108px) 0 0!important;display:grid!important;align-items:start!important;padding:0!important;overflow-y:auto!important;background:var(--cue-bg)!important}\n  .workspace .profile-preview-backdrop>.profile-preview{width:100%!important;max-width:none!important;min-height:0!important;max-height:none!important;margin:0!important;border:0!important;background:var(--cue-bg)!important}\n  .workspace .profile-preview>header{position:sticky!important;z-index:4!important;top:0!important;min-height:48px!important;padding:0 14px!important;background:color-mix(in srgb,var(--cue-bg) 96%,transparent)!important;backdrop-filter:blur(14px)!important}\n  .workspace .profile-preview>.profile-preview-hero{display:grid!important;align-content:end!important;width:calc(100% - 24px)!important;min-height:360px!important;height:52dvh!important;max-height:500px!important;margin:12px!important;padding:24px!important;box-sizing:border-box!important;overflow:hidden!important}\n  .workspace .profile-preview-hero>img{inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important}.workspace .profile-preview-hero h2{max-width:82%!important;font-size:clamp(2.8rem,15vw,4.8rem)!important;line-height:.9!important}.workspace .profile-preview>.profile-preview-body{width:100%!important;box-sizing:border-box!important;padding:20px 18px max(28px,env(safe-area-inset-bottom))!important}\n'''
if marker not in c:
    raise SystemExit('mobile marker missing')
if '.workspace .profile-preview-backdrop{position:fixed!important;z-index:80!important' not in c:
    c = c.replace(marker, marker + mobile, 1)
css.write_text(c)
